# Keep human handoff prose spaced without changing source IDs, paths or code.
def prose_space(text):
 protected=re.compile(r'(`[^`]*`|\$[^$]*\$)')
 pieces=protected.split(text)
 for i in range(0,len(pieces),2):
  pieces[i]=re.sub(r'(?<=\d)(?=(?:raw|point|curve|proof|mark|case|slot|tuple|shape|model|context|branch|choice|facet|objective|demand|part|record|file|manifest|command|output|seed|negative|normal|phase|target|valid|invalid|Apply|Analyse|Understand|minima|maxima|inflexion|calculus|motion|trig|visual|content|supplementary|parameter|sf|on\b|for\b))',' ',pieces[i])
  pieces[i]=re.sub(r'\b(all|All|the|The|exactly|only|after|before|plus|from|and|or)(?=\d)',r'\1 ',pieces[i])
 out=''.join(pieces)
 replacements={'assistants;23November2026':'assistants; 23 November 2026','newnormal':'new normal','rootclasses':'root classes','15vectorfixtures':'15 vector fixtures','trap3 sf':'trapezium 3 s.f.','One4 markshow-that':'One 4-mark show-that','extended9':'extended branch: 9 marks','examweights':'exam weights','deck19':'deck 19','modelconstruction notclaimed':'model construction not claimed','72negations':'72 negations','34/35allowance':'34/35 allowance','consistentintegrandrule':'consistent integrand rule','numericdigit':'numeric digit','3builds':'3 builds','planmanifest':'plan manifest','answer0':'answer 0','stageE':'stage E','allthree':'all three','full285':'full 285','R-form2022':'R-form 2022','table2022':'table 2022','reportPDF313':'report PDF 313','0for':'0 for','2022PDF301/2023PDF337':'2022 PDF 301 / 2023 PDF 337','the2025':'the 2025','the2023':'the 2023','same211':'same 211','D0same':'D0 same ','D1same':'D1 same ','branch910':'branch 910','rejected1777':'rejected 1777'}
 for before,after in replacements.items():out=out.replace(before,after)
 return out
(C/'plan-repair-d1-report.md').write_text(prose_space(text))
